   154	fn plugin_install(args: &[String]) -> std::io::Result<i32> {
   155	    let Some(source_arg) = args.first() else {
   156	        eprintln!("usage: herdr plugin install <owner>/<repo>[/subdir...] [--ref REF] [--yes]");
   157	        return Ok(2);
   158	    };
   159	    let source = match GithubPluginSource::parse(source_arg) {
   160	        Ok(source) => source,
   161	        Err(err) => {
   162	            eprintln!("{err}");
   163	            return Ok(2);
   164	        }
   165	    };
   166	    let mut requested_ref = None;
   167	    let mut yes = false;
   168	    let mut index = 1;
   169	    while index < args.len() {
   170	        match args[index].as_str() {
   171	            "--ref" => {
   172	                let Some(value) = required_value(args, &mut index, "--ref") else {
   173	                    return Ok(2);
   174	                };
   175	                requested_ref = Some(value);
   176	            }
   177	            "--yes" | "-y" => {
   178	                yes = true;
   179	                index += 1;
   180	            }
   181	            other => {
   182	                eprintln!("unknown option: {other}");
   183	                return Ok(2);
   184	            }
   185	        }
   186	    }
   187	
   188	    if !yes && !io::stdin().is_terminal() {
   189	        eprintln!("remote plugin install requires --yes when stdin is not interactive");
   190	        return Ok(2);
   191	    }
   192	
   193	    let temp_root = create_plugin_temp_dir("install")?;
   194	    let checkout = temp_root.join("checkout");
   195	    let install_result = (|| {
   196	        git_checkout(&source, requested_ref.as_deref(), &checkout)?;
   197	        let resolved_commit = git_output(&checkout, ["rev-parse", "HEAD"])?;
   198	        let manifest_root = source.manifest_root(&checkout);
   199	        let preview_plugin = load_cli_plugin_manifest(&manifest_root, true)?;
   200	        let existing = installed_plugin_info(&preview_plugin.plugin_id)?;
   201	        ensure_replacement_allowed(&preview_plugin, existing.as_ref())?;
   202	
   203	        let mut source_info =
   204	            source.to_source_info(requested_ref, resolved_commit, None, current_unix_ms());
   205	        print_install_preview(&preview_plugin, &source_info, existing.as_ref());
   206	        if !yes && !confirm("Install this plugin?")? {
   207	            eprintln!("plugin install cancelled");
   208	            return Ok(0);
   209	        }
   210	        if let Err(err) = run_plugin_build_commands(&preview_plugin, &manifest_root) {
   211	            eprintln!("{err}");
   212	            return Ok(1);
   213	        }
   214	        let post_build_plugin = load_cli_plugin_manifest(&manifest_root, true)?;
   215	        ensure_manifest_unchanged_after_build(&preview_plugin, &post_build_plugin)?;
   216	
   217	        let final_checkout = crate::plugin_paths::managed_checkout_path(&preview_plugin.plugin_id);
   218	        let backup_checkout = temp_root.join("previous-checkout");
   219	        let mut backup_moved = false;
   220	        if final_checkout.exists() {
   221	            std::fs::rename(&final_checkout, &backup_checkout)
   222	                .map_err(|err| plugin_checkout_lifecycle_error("replace", &final_checkout, err))?;
   223	            backup_moved = true;
   224	        }
   225	        let install_attempt = (|| {
   226	            if let Some(parent) = final_checkout.parent() {
   227	                std::fs::create_dir_all(parent).map_err(InstallFailure::Rollback)?;
   228	            }
   229	            std::fs::rename(&checkout, &final_checkout)
   230	                .map_err(|err| plugin_checkout_lifecycle_error("install", &final_checkout, err))
   231	                .map_err(InstallFailure::Rollback)?;
   232	
   233	            source_info.managed_path = Some(final_checkout.display().to_string());
   234	            let final_manifest_root = source.manifest_root(&final_checkout);
   235	            let mut plugin = load_cli_plugin_manifest(&final_manifest_root, true)
   236	                .map_err(InstallFailure::Rollback)?;
   237	            plugin.source = source_info.clone();
   238	            register_installed_plugin(plugin.clone(), source_info.clone())?;
   239	            Ok::<InstalledPluginInfo, InstallFailure>(plugin)
   240	        })();
   241	        let plugin = match install_attempt {
   242	            Ok(plugin) => plugin,
   243	            Err(InstallFailure::Rollback(err)) => {
   244	                let _ = std::fs::remove_dir_all(&final_checkout);
   245	                if backup_moved && backup_checkout.exists() {
   246	                    let _ = std::fs::rename(&backup_checkout, &final_checkout);
   247	                }
   248	                return Err(err);
   249	            }
   250	            Err(InstallFailure::KeepCheckout(err)) => return Err(err),
   251	        };
   252	        println!("Installed {} from {}.", plugin.plugin_id, source.display());
   253	        println!(
   254	            "Config: {}",
   255	            crate::plugin_paths::plugin_config_dir(&plugin.plugin_id).display()
   256	        );
   257	        Ok(0)
   258	    })();
   259	    let _ = std::fs::remove_dir_all(&temp_root);
   260	    install_result
   261	}
