   263	fn plugin_uninstall(args: &[String]) -> std::io::Result<i32> {
   264	    let Some(target) = args.first() else {
   265	        eprintln!("usage: herdr plugin uninstall <plugin_id|owner/repo[/subdir...]>");
   266	        return Ok(2);
   267	    };
   268	    if args.len() != 1 {
   269	        eprintln!("usage: herdr plugin uninstall <plugin_id|owner/repo[/subdir...]>");
   270	        return Ok(2);
   271	    }
   272	
   273	    let (plugin_id, existing) = match GithubPluginSource::parse(target) {
   274	        Ok(source) => {
   275	            let existing = installed_plugin_by_github_source(&source)?;
   276	            let Some(existing) = existing else {
   277	                eprintln!("plugin not installed: {}", source.display());
   278	                return Ok(1);
   279	            };
   280	            (existing.plugin_id.clone(), Some(existing))
   281	        }
   282	        Err(_) => {
   283	            let existing = match live_installed_plugin_info(target) {
   284	                Ok(plugin) => plugin,
   285	                Err(err) if is_connection_error(&err) => registry_plugin_info(target),
   286	                Err(err) => return Err(err),
   287	            };
   288	            (target.clone(), existing)
   289	        }
   290	    };
   291	
   292	    match super::send_request(&Request {
   293	        id: "cli:plugin".into(),
   294	        method: Method::PluginUnlink(PluginUnlinkParams {
   295	            plugin_id: plugin_id.clone(),
   296	        }),
   297	    }) {
   298	        Ok(response) => {
   299	            if response.get("error").is_some() {
   300	                return super::print_response(&response);
   301	            }
   302	            if response["result"]["removed"].as_bool() == Some(false) {
   303	                eprintln!("plugin not installed: {target}");
   304	                return Ok(1);
   305	            }
   306	        }
   307	        Err(err) if is_connection_error(&err) => {
   308	            let (removed, _) = crate::persist::plugin_registry::update(|plugins| {
   309	                let before = plugins.len();
   310	                plugins.retain(|plugin| plugin.plugin_id != plugin_id);
   311	                before != plugins.len()
   312	            })?;
   313	            if !removed {
   314	                eprintln!("plugin not installed: {target}");
   315	                return Ok(1);
   316	            }
   317	        }
   318	        Err(err) => return Err(err),
   319	    }
   320	
   321	    if let Some(plugin) = existing.as_ref() {
   322	        remove_managed_plugin_files(plugin)?;
   323	    }
   324	    println!("Uninstalled {plugin_id}.");
   325	    Ok(0)
   326	}
